<script setup>
import {ref,onMounted} from 'vue'
import {api,post} from '../api'
import KnowledgeDetail from '../components/KnowledgeDetail.vue'
const foods=ref('')
const members=ref([]),memberId=ref(''),report=ref(null),error=ref(''),busy=ref(false)
async function load(){report.value=null;if(!memberId.value)return;busy.value=true;error.value='';try{report.value=await post('/interactions/check',{member_id:memberId.value,foods:foods.value.split(/[、,，]/).map(value=>value.trim()).filter(Boolean)})}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{try{members.value=await api('/members');memberId.value=members.value[0]?.id||'';await load()}catch(e){error.value=e.message}})
</script>
<template><p class="subtitle">检查药品组合和成员角色对应的规则。填写食物或饮品名称后，可一起检查。</p><label>食物或饮品（可选，顿号分隔）<input v-model="foods" :disabled="busy" @input="report=null"></label><div class="toolbar risk-controls"><label>查看成员<select v-model="memberId" @change="foods='';load()" :disabled="busy"><option v-for="m in members" :key="m.id" :value="m.id">{{m.name}}</option></select></label><button @click="load" :disabled="busy || !memberId">{{busy?'检查中…':'重新检查'}}</button></div><p class="error" v-if="error">{{error}}</p><template v-if="report"><section class="hero"><h2>{{report.member_name}}的用药风险</h2><p>{{report.count}} 项 · {{report.highest_level}}</p></section><p class="feedback" v-if="report.count">{{report.message}}</p><p class="subtitle" v-else>当前没有命中已发布的用药风险规则。药箱为空时也会显示 0 项。</p><p class="error" v-if="report.missing.length">以下药品资料不足：{{report.missing.join('、')}}。不能据此判断安全。</p><section class="panel" v-for="item in report.items" :key="item.id"><h2>{{item.kind==='food_rule'?'食物饮品风险':item.kind==='population_rule'?'特殊人群风险':'药品组合风险'}}</h2><p>{{item.drugs.join(' ＋ ')}}<span v-if="item.kind!=='rule'"> · {{item.right}}</span></p><KnowledgeDetail :entry="item"/></section><section class="panel" v-if="report.population_notes.length"><h2>特殊人群提示</h2><p class="subtitle">请结合成员年龄及过敏史核对；当前为资料提示，不作个体诊断。</p><p v-for="n in report.population_notes" :key="n.drug">{{n.drug}}：{{n.text}}</p></section></template></template>
